32	import org.jkiss.dbeaver.model.struct.DBSTypedObjectExt3;
33	import org.jkiss.utils.CommonUtils;
34	
35	/**
36	 * AbstractAttribute
37	 */
38	public abstract class AbstractAttribute implements DBSAttributeBase, DBSTypedObjectExt2, DBSTypedObjectExt3, DBPToolTipObject, DBPNamedObject2
39	{
40	    protected String name;
41	    protected int valueType;
42	    protected long maxLength;
43	    protected boolean required;
44	    protected boolean autoGenerated;
45	    protected int scale;
46	    protected int precision;
47	    protected String typeName;
48	    protected int ordinalPosition;
49	
50	    protected AbstractAttribute()
51	    {
52	    }
53	
54	    // Copy constructor
55	    protected AbstractAttribute(DBSAttributeBase source)
56	    {
57	        this(
58	            source.getName(),
59	            source.getTypeName(),
60	            source.getTypeID(),
61	            source.getOrdinalPosition(),
62	            source.getMaxLength(),
63	            source.getScale(),
64	            source.getPrecision(),
65	            source.isRequired(),
66	            source.isAutoGenerated());
67	    }
68	
69	    protected AbstractAttribute(
70	            String name,
71	            String typeName,
72	            int valueType,
73	            int ordinalPosition,
74	            long maxLength,
75	            Integer scale,
76	            Integer precision,
77	            boolean required,
78	            boolean autoGenerated)
79	    {
80	        this.name = name;
81	        this.valueType = valueType;
82	        this.maxLength = maxLength;
83	        this.scale = scale == null ? -1 : scale;
84	        this.precision = precision == null ? - 1 : precision;
85	        this.required = required;
86	        this.autoGenerated = autoGenerated;
87	        this.typeName = typeName;
88	        this.ordinalPosition = ordinalPosition;
89	    }
90	
91	    @NotNull
92	    @Override
93	    @Property(viewable = true, order = 10, valueTransformer = DBObjectNameCaseTransformer.class)
94	    public String getName()
95	    {
96	        return name;
97	    }
98	
99	    @Override
100	    public void setName(@NotNull String columnName)
101	    {
102	        this.name = columnName;
103	    }
104	
105	    @Property(viewable = true, order = 15, valueRenderer = DBPositiveNumberTransformer.class)
106	    public int getOrdinalPosition()
107	    {
108	        return ordinalPosition;
109	    }
110	
111	    public void setOrdinalPosition(int ordinalPosition)
112	    {
113	        this.ordinalPosition = ordinalPosition;
114	    }
115	
116	    @NotNull
117	    @Override
118	    @Property(viewable = true, order = 20)
119	    public String getTypeName()
120	    {
121	        return typeName;
122	    }
123	
124	    @NotNull
125	    @Override
126	    public String getFullTypeName() {
127	        return DBUtils.getFullTypeName(this);
128	    }
129	
130	    @Override
131	    public void setTypeName(@NotNull String typeName) throws DBException
132	    {
133	        this.typeName = typeName;
134	    }
135	
136	    @Override
137	    public void setFullTypeName(@NotNull String fullTypeName) throws DBException {
138	        String plainTypeName;
139	        int divPos = fullTypeName.indexOf("(");
140	        if (divPos == -1) {
141	            plainTypeName = fullTypeName;
142	            validateTypeName(plainTypeName);
143	        } else {
144	            plainTypeName = fullTypeName.substring(0, divPos);
145	            validateTypeName(plainTypeName);
146	            int divPos2 = fullTypeName.indexOf(')', divPos);
147	            if (divPos2 != -1) {
148	                String modifiers = fullTypeName.substring(divPos + 1, divPos2);
149	                int divPos3 = modifiers.indexOf(',');
150	                if (divPos3 == -1) {
151	                    maxLength = precision = CommonUtils.toInt(modifiers, -1);
152	                } else {
153	                    precision= CommonUtils.toInt(modifiers.substring(0, divPos3).trim());
154	                    scale = CommonUtils.toInt(modifiers.substring(divPos3 + 1).trim());
155	                }
156	            }
157	        }
158	        setTypeName(plainTypeName);
159	    }
160	
161	    protected void validateTypeName(String typeName) throws DBException {
162	
163	    }
164	
165	    @Override
166	    public int getTypeID()
167	    {
168	        return valueType;
169	    }
170	
171	    public void setValueType(int valueType)
172	    {
173	        this.valueType = valueType;
174	    }
175	
176	    @Override
177	    @Property(viewable = true, order = 40)
178	    public long getMaxLength()
179	    {
180	        return maxLength;
181	    }
182	
183	    @Override
184	    public void setMaxLength(long maxLength)
185	    {
186	        this.maxLength = maxLength;
187	    }
188	
189	    @Override
190	    @Property(viewable = false, valueRenderer = DBPositiveNumberTransformer.class, order = 41)
191	    public Integer getScale()
192	    {
193	        return scale == -1 ? null : scale;
194	    }
195	
196	    @Override
197	    public void setScale(@Nullable Integer scale)
198	    {
199	        this.scale = scale == null ? -1 : scale;
200	    }
201	
202	    @Nullable
203	    @Override
204	    @Property(viewable = false, valueRenderer = DBPositiveNumberTransformer.class, order = 42)
205	    public Integer getPrecision()
206	    {
207	        return precision == -1 ? null : precision;
208	    }
209	
210	    @Override
211	    public void setPrecision(@Nullable Integer precision)
212	    {
213	        this.precision = precision == null ? -1 : precision;
214	    }
215	
216	    @Property(viewable = true, order = 50)
217	    public boolean isRequired()
218	    {
219	        return required;
220	    }
221	
222	    @Override
223	    public void setRequired(boolean required)
224	    {
225	        this.required = required;
226	    }
227	
228	    @Property(viewable = true, order = 55)
229	    public boolean isAutoGenerated() {
230	        return autoGenerated;
231	    }
232	
233	    public void setAutoGenerated(boolean autoGenerated) {
234	        this.autoGenerated = autoGenerated;
235	    }
236	
237	    @Override
238	    public long getTypeModifiers() {
239	        return 0;
240	    }
241	
242	    @Nullable
243	    public String getDescription()
244	    {
245	        return null;
246	    }
247	
248	    public boolean isPersisted()
249	    {
250	        return true;
251	    }
252	
253	    @Override
254	    public String getObjectToolTip() {
255	        return getFullTypeName();
256	    }
257	
258	    @Override
259	    public String toString() {
260	        return name + ", type=" + typeName + ", pos=" + ordinalPosition;
261	    }
262	
263	    protected void onChangeDataType(DBSTypedObject oldType, DBSTypedObject newType) {
264	        if (oldType != null && newType != null) {
265	            DBPDataKind newTypeDataKind = newType.getDataKind();
266	            if (oldType.getDataKind() != newTypeDataKind) {
267	                long maxLength = newType.getMaxLength();
268	                if ((newTypeDataKind == DBPDataKind.STRING || newTypeDataKind == DBPDataKind.CONTENT) && maxLength > this.maxLength) {
269	                    this.maxLength = 100;
270	                } else {
271	                    this.maxLength = CommonUtils.toInt(maxLength, -1);
272	                }
273	                this.precision = CommonUtils.toInt(newType.getPrecision(), -1);
274	                this.scale = CommonUtils.toInt(newType.getScale(), -1);
275	            }
276	        }
277	    }
278	
279	}
