35	public class DefaultValueHandler extends BaseValueHandler {
36	
37	    public static final DefaultValueHandler INSTANCE = new DefaultValueHandler();
38	
39	    @NotNull
40	    @Override
41	    public Class<Object> getValueObjectType(@NotNull DBSTypedObject attribute)
42	    {
43	        return Object.class;
44	    }
45	
46	    @Override
47	    public Object fetchValueObject(
48	        @NotNull DBCSession session,
49	        @NotNull DBCResultSet resultSet,
50	        @NotNull DBSTypedObject type,
51	        int index) throws DBCException
52	    {
53	        return resultSet.getAttributeValue(index);
54	    }
55	
56	    @Override
57	    public void bindValueObject(
58	        @NotNull DBCSession session,
59	        @NotNull DBCStatement statement,
60	        @NotNull DBSTypedObject type,
61	        int index,
62	        Object value) throws DBCException
63	    {
64	        String objectName = type instanceof DBPNamedObject namedObject ? DBUtils.getObjectFullName(namedObject, DBPEvaluationContext.UI) : type.getTypeName();
65	        throw new DBCException("Parameter [" + objectName + "] value [" + DBValueFormatting.getDefaultValueDisplayString(value, DBDDisplayFormat.UI) + "] binding not supported");
66	    }
67	
68	    @Override
69	    public Object getValueFromObject(@NotNull DBCSession session, @NotNull DBSTypedObject type, @Nullable Object object, boolean copy, boolean validateValue) throws DBCException
70	    {
71	        return object;
72	    }
73	
74	}
