23	
24	import java.lang.reflect.InvocationTargetException;
25	
26	/**
27	 * Abstract Database Job
28	 */
29	public class SystemJob extends AbstractJob
30	{
31	    private final DBRRunnableWithProgress runnable;
32	    public SystemJob(String name, DBRRunnableWithProgress runnable) {
33	        super(name);
34	        setSystem(true);
35	        setUser(false);
36	        this.runnable = runnable;
37	    }
38	
39	    @NotNull
40	    @Override
41	    protected IStatus run(@NotNull DBRProgressMonitor monitor) {
42	        try {
43	            runnable.run(monitor);
44	        } catch (InvocationTargetException e) {
45	            return GeneralUtils.makeExceptionStatus(e.getTargetException());
46	        } catch (InterruptedException e) {
47	            return Status.CANCEL_STATUS;
48	        }
49	        return Status.OK_STATUS;
50	    }
51	
52	}

