30	import org.jkiss.dbeaver.model.struct.DBSDataManipulator;
31	import org.jkiss.utils.ArrayUtils;
32	import org.jkiss.utils.CommonUtils;
33	
34	import java.util.ArrayList;
35	import java.util.Arrays;
36	import java.util.List;
37	import java.util.Map;
38	
39	/**
40	 * Execute batch.
41	 * Can be used in JDBC or any other underlying DB APIs
42	 *
43	*/
44	public abstract class ExecuteBatchImpl implements DBSDataManipulator.ExecuteBatch {
45	
46	    private static final Log log = Log.getLog(ExecuteBatchImpl.class);
47	
48	    protected final DBSAttributeBase[] attributes;
49	    protected final List<Object[]> values = new ArrayList<>();
50	    protected final DBDDataReceiver keysReceiver;
51	    protected final boolean reuseStatement;
52	
53	    /**
54	     * Constructs new batch
55	     * @param attributes array of attributes used in batch
56	     * @param keysReceiver keys receiver (or null)
57	     * @param reuseStatement true if engine should reuse single prepared statement for each execution.
58	     */
59	    protected ExecuteBatchImpl(@NotNull DBSAttributeBase[] attributes, @Nullable DBDDataReceiver keysReceiver, boolean reuseStatement)
60	    {
61	        this.attributes = attributes;
62	        this.keysReceiver = keysReceiver;
63	        this.reuseStatement = reuseStatement;
64	    }
65	
66	    @NotNull
67	    @Override
68	    public DBSDataManipulator.ExecuteBatch add(@NotNull Object[] attributeValues) throws DBCException {
69	        if (!ArrayUtils.isEmpty(attributes) && ArrayUtils.isEmpty(attributeValues)) {
70	            throw new DBCException("Bad attribute values: " + Arrays.toString(attributeValues));
71	        }
72	        values.add(attributeValues);
73	        return this;
74	    }
75	
76	    @NotNull
77	    @Override
78	    public DBCStatistics execute(@NotNull DBCSession session, @NotNull Map<String, Object> options) throws DBException {
79	        return processBatch(session, null, options);
80	    }
81	
82	    @NotNull
83	    @Override
84	    public void generatePersistActions(@NotNull DBCSession session, @NotNull List<DBEPersistAction> actions, @NotNull Map<String, Object> options) throws DBException {
85	        processBatch(session, actions, options);
86	    }
87	
88	    /**
89	     * Execute batch OR generate batch script.
90	     * @param session    session
91	     * @param actions    script actions. If not null then no execution will be done
92	     * @param options
93	     * @return execution statistics
94	     * @throws DBCException
95	     */
96	    @NotNull
97	    DBCStatistics processBatch(@NotNull DBCSession session, @Nullable List<DBEPersistAction> actions, Map<String, Object> options) throws DBException
98	    {
99	        //session.getProgressMonitor().subTask("Save batch (" + values.size() + ")");
100	        DBDValueHandler[] handlers = new DBDValueHandler[attributes.length];
101	        for (int i = 0; i < attributes.length; i++) {
102	            if (attributes[i] instanceof DBDAttributeBinding) {
103	                handlers[i] = ((DBDAttributeBinding)attributes[i]).getValueHandler();
104	            } else {
105	                handlers[i] = DBUtils.findValueHandler(session, attributes[i]);
106	            }
107	        }
108	
109	        boolean useBatch = session.getDataSource().getInfo().supportsBatchUpdates() && reuseStatement && !CommonUtils.toBoolean(options.get(DBSDataManipulator.OPTION_DISABLE_BATCHES));
110	        if (values.size() <= 1) {
111	            useBatch = false;
112	        }
113	        boolean skipBindValues = CommonUtils.toBoolean(options.get(DBSDataManipulator.OPTION_SKIP_BIND_VALUES));
114	        if (skipBindValues) {
115	            useBatch = false;
116	        }
117	
118	        DBCStatistics statistics = new DBCStatistics();
119	        DBCStatement statement = null;
120	
121	        try {
122	            // Here we'll try to reuse prepared statement.
123	            // It makes a great sense in case of data transfer where we need millions of inserts.
124	            // We must be aware of nulls because actual insert statements may differ depending on null values.
125	            // So if row nulls aren't the same as in previous row we need to prepare new statement and restart batch.
126	            // Quite complicated but works.
127	            boolean[] prevNulls = new boolean[attributes.length];
128	            boolean[] nulls = new boolean[attributes.length];
129	            int statementsInBatch = 0;
130	
131	            for (int rowIndex = 0; rowIndex < values.size(); rowIndex++) {
132	                Object[] rowValues = values.get(rowIndex);
133	                if (session.getProgressMonitor().isCanceled()) {
134	                    break;
135	                }
136	                if (rowIndex > 0 && rowIndex % 100 == 0) {
137	                    //session.getProgressMonitor().subTask("Save batch (" + rowIndex + " of " + values.size() + ")");
138	                }
139	
140	                boolean reuse = !skipBindValues && reuseStatement;
141	                if (reuse) {
142	                    for (int i = 0; i < rowValues.length; i++) {
143	                        nulls[i] = DBUtils.isNullValue(rowValues[i]);
144	                    }
145	                    if (!Arrays.equals(prevNulls, nulls) && statementsInBatch > 0) {
146	                        reuse = false;
147	                    }
148	                    System.arraycopy(nulls, 0, prevNulls, 0, nulls.length);
149	                    if (!reuse && statementsInBatch > 0) {
150	                        // Flush batch
151	                        if (actions == null) {
152	                            flushBatch(statistics, statement);
153	                        }
154	                        DBUtils.closeSafely(statement);
155	                        statement = null;
156	                        statementsInBatch = 0;
157	                        reuse = true;
158	                    }
159	                }
160	                if (statement == null || !reuse) {
161	                    statement = prepareStatement(session, handlers, rowValues, options);
162	                    statistics.setQueryText(statement.getQueryString());
163	                    statistics.addStatementsCount();
164	                }
165	                try {
166	                    if (!skipBindValues) {
167	                        bindStatement(handlers, statement, rowValues);
168	                    }
169	                    if (actions == null) {
170	                        if (useBatch) {
171	                            statement.addToBatch();
172	                            statementsInBatch++;
173	                        } else {
174	                            // Execute each row separately
175	                            long startTime = System.currentTimeMillis();
176	                            executeStatement(statistics, statement);
177	                            statistics.addExecuteTime(System.currentTimeMillis() - startTime);
178	
179	                            long rowCount = statement.getUpdateRowCount();
180	                            if (rowCount > 0) {
181	                                statistics.addRowsUpdated(rowCount);
182	                            }
183	
184	                            // Read keys
185	                            if (keysReceiver != null) {
186	                                try {
187	                                    readKeys(statement.getSession(), statement, keysReceiver);
188	                                } catch (Exception e) {
189	                                    log.warn("Error reading auto-generated keys", e);
190	                                }
191	                            }
192	                        }
193	                    } else {
194	                        String queryString = formatQueryParameters(session, statement.getQueryString(), handlers, rowValues);
195	                        actions.add(
196	                            new SQLDatabasePersistAction(
197	                                "Execute statement",
198	                                queryString));
199	                    }
200	                } finally {
201	                    if (!reuse && !useBatch) {
202	                        DBUtils.closeSafely(statement);
203	                    }
204	                }
205	            }
206	
207	            if (statementsInBatch > 0) {
208	                if (actions == null) {
209	                    flushBatch(statistics, statement);
210	                }
211	                DBUtils.closeSafely(statement);
212	                statement = null;
213	            }
214	            values.clear();
215	        } finally {
216	            if (reuseStatement && statement != null) {
217	                DBUtils.closeSafely(statement);
218	            }
219	            if (!useBatch && !values.isEmpty()) {
220	                values.clear();
221	            }
222	        }
223	
224	        return statistics;
225	    }
226	
227	    protected int getNextUsedParamIndex(Object[] attributeValues, int paramIndex) {
228	        paramIndex++;
229	        // we need to skip all nullable values because they are already set in the statement
230	        while (paramIndex < attributeValues.length && attributeValues[paramIndex] instanceof DBDNull) {
231	            paramIndex++;
232	        }
233	        return paramIndex;
234	    }
235	
236	    String formatQueryParameters(DBCSession session, String queryString, DBDValueHandler[] handlers, Object[] rowValues) {
237	        if (handlers.length == 0) {
238	            return queryString;
239	        }
240	        if (CommonUtils.isEmpty(queryString)) {
241	            return queryString;
242	        }
243	        int length = queryString.length();
244	        StringBuilder formatted = new StringBuilder(length * 2);
245	        int paramIndex = -1;
246	
247	        for (int i = 0; i < length; i++) {
248	            char c = queryString.charAt(i);
249	            switch (c) {
250	                case '?': {
251	                    paramIndex = getNextUsedParamIndex(rowValues, paramIndex);
252	                    if (paramIndex >= handlers.length) {
253	                        log.error("Parameter index out of range (" + paramIndex + " > " + handlers.length + ")");
254	                        continue;
255	                    }
256	                    Object paramValue = SQLUtils.convertValueToSQL(
257	                        session.getDataSource(),
258	                        attributes[paramIndex],
259	                        handlers[paramIndex],
260	                        rowValues[paramIndex],
261	                        DBDDisplayFormat.NATIVE,
262	                        false);
263	                    formatted.append(paramValue);
264	                    continue;
265	                }
266	                case ':': {
267	                    // FIXME: process named parameters
268	                    break;
269	                }
270	                case '\'':
271	                case '"': {
272	                    formatted.append(c);
273	                    for (int k = i + 1; k < length; k++) {
274	                        char c2 = queryString.charAt(k);
275	                        if (c2 == c && queryString.charAt(k - 1) != '\\') {
276	                            i = k;
277	                            c = c2;
278	                            break;
279	                        } else {
280	                            formatted.append(c2);
281	                        }
282	                    }
283	                    break;
284	                }
285	            }
286	            formatted.append(c);
287	        }
288	
289	        return formatted.toString();
290	    }
291	
292	    void flushBatch(DBCStatistics statistics, DBCStatement statement) throws DBCException {
293	        long startTime = System.currentTimeMillis();
294	        long[] updatedRows = statement.executeStatementBatch();
295	        statistics.addExecuteTime(System.currentTimeMillis() - startTime);
296	        if (!ArrayUtils.isEmpty(updatedRows)) {
297	            for (long rows : updatedRows) {
298	                if (rows < 0) {
299	                    // In some cases (e.g. JDBC API) negative means "unknown".
300	                    // "Statement.SUCCESS_NO_INFO — the command was processed successfully, but the number of rows affected is unknown"
301	                    // But we are quite sure that it has to be 1 (because each statement inserts/deletes/updates a single row)
302	                    // The only exception is bulk delete  (without WHERE condition)
303	                    if (!ArrayUtils.isEmpty(attributes)) {
304	                        rows = 1;
305	                    }
306	                }
307	                statistics.addRowsUpdated(rows);
308	            }
309	        }
310	        saveExecuteWarnings(statistics, statement);
311	    }
312	
313	    protected void executeStatement(DBCStatistics statistics, DBCStatement statement) throws DBCException {
314	        statement.executeStatement();
315	        saveExecuteWarnings(statistics, statement);
316	    }
317	
318	    private void saveExecuteWarnings(DBCStatistics statistics, DBCStatement statement) throws DBCException {
319	        Throwable[] warnings = statement.getStatementWarnings();
320	        if (warnings != null) {
321	            for (Throwable w : warnings) {
322	                statistics.addWarning(w);
323	            }
324	        }
325	    }
326	
327	    @Override
328	    public void close()
329	    {
330	    }
331	
332	    private void readKeys(@NotNull DBCSession session, @NotNull DBCStatement dbStat, @NotNull DBDDataReceiver keysReceiver)
333	        throws DBException
334	    {
335	        DBCResultSet dbResult;
336	        try {
337	            dbResult = dbStat.openGeneratedKeysResultSet();
338	        }
339	        catch (Throwable e) {
340	            log.debug("Error obtaining generated keys", e); //$NON-NLS-1$
341	            return;
342	        }
343	        if (dbResult == null) {
344	            return;
345	        }
346	        try (dbResult) {
347	            DBDDataReceiver.startFetchWorkflow(keysReceiver, session, dbResult, -1, -1);
348	            while (dbResult.nextRow()) {
349	                keysReceiver.fetchRow(session, dbResult);
350	            }
351	        }
352	    }
353	
354	    @NotNull
355	    protected abstract DBCStatement prepareStatement(@NotNull DBCSession session, DBDValueHandler[] handlers, Object[] attributeValues, Map<String, Object> options) throws DBCException;
356	
357	    protected abstract void bindStatement(@NotNull DBDValueHandler[] handlers, @NotNull DBCStatement statement, Object[] attributeValues) throws DBCException;
358	
359	
360	}
