78	    public void serializeDocument(@NotNull DBRProgressMonitor monitor, @NotNull Writer writer) throws IOException, DBException {
79	        try {
80	            Transformer transformer = TransformerFactory.newInstance().newTransformer();
81	            Result output = new StreamResult(writer);
82	
83	            transformer.transform(
84	                new DOMSource(document),
85	                output);
86	        } catch (Exception e) {
87	            throw new DBException("Error serializing XML document", e);
88	        }
89	    }
90	
