95	            DOMResult output = new DOMResult();
96	
97	            transformer.transform(
98	                new StreamSource(reader),
99	                output);
100	            document = (Document) output.getNode();
101	            modified = true;
102	        } catch (Exception e) {
103	            throw new DBException("Error transforming XML document", e);
104	        }
105	    }
